// Normalize the webhook payload and assemble the final feedback email.
const b = $input.item.json.body || $input.item.json;
if (!b.agentEmail) throw new Error('agentEmail is required');
if (!b.conversationId) throw new Error('conversationId is required');

const contactName = b.contact || 'N/A';
let emailContent = String(b.emailContent || '');
if (emailContent) {
  emailContent = emailContent
    .replace(/- Customer Name:[^\n\r]*/g, `- Customer Name: ${contactName}`)
    .replace(/(\n*)Guidelines:/g, '\n\nGuidelines:');
}

// Light cleanup only: the supervisor's wording is preserved.
const feedbackText = String(b.comments || '').trim();
let cleaned = feedbackText.replace(/!+/g, '!').replace(/\s+/g, ' ').trim();
if (cleaned) {
  cleaned = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
  if (!/[.!?]$/.test(cleaned)) cleaned += '.';
}
if (emailContent && feedbackText && cleaned !== feedbackText) {
  emailContent = emailContent.split(feedbackText).join(cleaned);
}

// Rule-based type, used for the record only.
const lower = feedbackText.toLowerCase();
let feedbackType = 'verbatim';
if (/\b(warning|serious|policy violation|repeated)\b/i.test(feedbackText)) {
  feedbackType = 'warning';
} else if (/\b(however|make sure|should|consider|improve|next time|please|recommend)\b/i.test(lower)) {
  feedbackType = 'corrective';
} else if (
  /\b(perfect|outstanding|great job|good job|well done|keep it up)\b/i.test(lower) &&
  !/\b(however|but|although)\b/i.test(lower)
) {
  feedbackType = 'positive';
}

return {
  json: {
    agent: b.agent || 'Agent',
    agentEmail: b.agentEmail,
    conversationId: b.conversationId,
    contact: b.contact || '',
    phone: b.phone || 'N/A',
    date: b.date || '',
    totalScore: b.totalScore ?? 0,
    passed: b.passed ?? false,
    scoredBy: b.scoredBy || '',
    comments: b.comments || '',
    feedbackType,
    emailSubject: `Quality feedback - ${b.agent || 'Agent'}`,
    finalEmailBody: emailContent,
    idempotencyKey: `feedback:${b.conversationId}`,
    receivedAt: new Date().toISOString(),
  },
};
